/** About Inkleaf: name, version, upstream credit, AGPL-3.0 notice, source and notices links. */
import { h, svg, trapFocus } from './dom';
import { getDesk } from './desk';
import { logoMark } from './icons';

import { APP_NAME, SOURCE_URL, UPSTREAM_URL } from './app-info';

/** Third-party notices page shipped in the app (generated by scripts/gen-notices.mjs). */
export const NOTICES_PATH = '/third-party-notices.html';

let open = false;

export function openAbout(): void {
  if (open) return;
  open = true;
  const prevFocus = document.activeElement as HTMLElement | null;
  const version = getDesk()?.version || '';

  const closeBtn = h('button', {
    class: 'dk-btn dk-btn-primary',
    text: 'Close',
    attrs: { type: 'button' },
  });

  const ext = (href: string, text: string) =>
    h('a', {
      class: 'dk-link',
      text,
      attrs: { href, target: '_blank', rel: 'noopener noreferrer' },
    });

  const dialog = h(
    'div',
    {
      class: 'dk-dialog dk-about',
      attrs: {
        role: 'dialog',
        'aria-modal': 'true',
        'aria-labelledby': 'dk-about-title',
        'aria-describedby': 'dk-about-desc',
        tabindex: -1,
      },
    },
    h('div', { class: 'dk-about-mark' }, svg(logoMark(56))),
    h('h2', {
      class: 'dk-about-name',
      text: APP_NAME,
      attrs: { id: 'dk-about-title' },
    }),
    h('p', {
      class: 'dk-about-version',
      text: version ? `Version ${version}` : 'Version unknown',
    }),
    h('p', {
      class: 'dk-about-lead',
      text: 'PDF tools that run entirely on your computer. Your files never leave it.',
      attrs: { id: 'dk-about-desc' },
    }),
    h(
      'div',
      { class: 'dk-about-body' },
      h(
        'p',
        {},
        'Based on ',
        ext(UPSTREAM_URL, 'BentoPDF'),
        ' by alam00000, AGPL-3.0.'
      ),
      h(
        'p',
        {},
        'Inkleaf is free software under the GNU AGPL-3.0; source code available at ',
        ext(SOURCE_URL, SOURCE_URL.replace(/^https:\/\//, '')),
        '.'
      ),
      h(
        'p',
        {},
        h('a', {
          class: 'dk-link',
          text: 'Third-party notices',
          attrs: { href: NOTICES_PATH },
        })
      )
    ),
    h('div', { class: 'dk-dialog-actions' }, closeBtn)
  );
  const scrim = h('div', { class: 'dk-scrim' }, dialog);
  const release = trapFocus(dialog);

  const close = () => {
    if (!open) return;
    open = false;
    release();
    document.removeEventListener('keydown', onKey, true);
    scrim.classList.add('is-closing');
    window.setTimeout(() => scrim.remove(), 120);
    if (prevFocus && prevFocus.isConnected) prevFocus.focus();
  };
  function onKey(e: KeyboardEvent) {
    if (e.key === 'Escape') {
      e.preventDefault();
      e.stopPropagation();
      close();
    }
  }
  document.addEventListener('keydown', onKey, true);
  closeBtn.addEventListener('click', close);
  scrim.addEventListener('mousedown', (e) => {
    if (e.target === scrim) close();
  });
  document.body.append(scrim);
  closeBtn.focus();
}
